export interface TourStep {
  selector: string;
  title: string;
  body: string;
}

const STORAGE_KEY_PREFIX = 'omar-text-editor-tour-seen-';

export function hasTourBeenSeen(tourId: string): boolean {
  try {
    return localStorage.getItem(STORAGE_KEY_PREFIX + tourId) === '1';
  } catch {
    return false;
  }
}

export function markTourSeen(tourId: string): void {
  try {
    localStorage.setItem(STORAGE_KEY_PREFIX + tourId, '1');
  } catch {
    // localStorage unavailable — the tour will simply show again next
    // load, which is an acceptable degradation, not worth surfacing.
  }
}

export function resetTourSeen(tourId: string): void {
  try {
    localStorage.removeItem(STORAGE_KEY_PREFIX + tourId);
  } catch {
    // Same rationale as markTourSeen.
  }
}
