// Blockquote toggle, horizontal rule insertion, and margin-based
// indent/outdent for non-list blocks.

function getRange(): Range | null {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0) return null;
  return sel.getRangeAt(0);
}

function findAncestor(root: HTMLElement, node: Node, tags: string[]): HTMLElement | null {
  let current: Node | null = node;
  while (current && current !== root.parentNode) {
    if (current.nodeType === Node.ELEMENT_NODE && tags.includes((current as Element).tagName.toLowerCase())) {
      return current as HTMLElement;
    }
    current = current.parentNode;
  }
  return null;
}

function findBlock(root: HTMLElement, node: Node): HTMLElement | null {
  return findAncestor(root, node, ['p', 'div', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'blockquote']);
}

function setCaretAt(node: Node, offset: number): void {
  const range = document.createRange();
  range.setStart(node, offset);
  range.setEnd(node, offset);
  const sel = window.getSelection();
  sel?.removeAllRanges();
  sel?.addRange(range);
}

export function toggleBlockquote(root: HTMLElement): void {
  const range = getRange();
  if (!range) return;

  const existing = findAncestor(root, range.commonAncestorContainer, ['blockquote']);
  if (existing) {
    const p = document.createElement('p');
    while (existing.firstChild) p.appendChild(existing.firstChild);
    existing.parentNode?.replaceChild(p, existing);
    setCaretAt(p, p.childNodes.length);
    return;
  }

  const block = findBlock(root, range.commonAncestorContainer);
  if (!block) return;

  const quote = document.createElement('blockquote');
  block.parentNode?.replaceChild(quote, block);
  quote.appendChild(block);
  setCaretAt(block, block.childNodes.length);
}

export function isBlockquoteActive(root: HTMLElement): boolean {
  const range = getRange();
  if (!range) return false;
  return findAncestor(root, range.commonAncestorContainer, ['blockquote']) !== null;
}

export function insertHorizontalRule(root: HTMLElement): void {
  const range = getRange();
  if (!range) return;

  const hr = document.createElement('hr');
  const block = findBlock(root, range.commonAncestorContainer);

  if (block) {
    block.parentNode?.insertBefore(hr, block.nextSibling);
  } else {
    range.insertNode(hr);
  }

  const p = document.createElement('p');
  p.innerHTML = '<br>';
  hr.parentNode?.insertBefore(p, hr.nextSibling);
  setCaretAt(p, 0);
}

const INDENT_STEP_PX = 40;

export function indentBlock(root: HTMLElement): void {
  const range = getRange();
  if (!range) return;
  const block = findBlock(root, range.commonAncestorContainer);
  if (!block) return;

  const current = parseInt(block.style.marginLeft || '0', 10);
  block.style.marginLeft = `${current + INDENT_STEP_PX}px`;
}

export function outdentBlock(root: HTMLElement): void {
  const range = getRange();
  if (!range) return;
  const block = findBlock(root, range.commonAncestorContainer);
  if (!block) return;

  const current = parseInt(block.style.marginLeft || '0', 10);
  const next = Math.max(0, current - INDENT_STEP_PX);
  if (next === 0) {
    block.style.removeProperty('margin-left');
  } else {
    block.style.marginLeft = `${next}px`;
  }
}
