import type { Editor } from '../../core/Editor';
import { registerPlugin } from '../../core/Editor';
import { Dialog } from '../../ui/Dialog';
import { Notification } from '../../ui/Notification';
import { registerToolbarButton } from '../../ui/Toolbar';
import { ContextMenuItem } from '../../ui/ContextMenu';
import {
  insertEmbed,
  getSelectedEmbed,
  getEmbedSrc,
  updateEmbed,
  removeEmbed,
} from '../../core/Embed';
import { setMediaAlign, setMediaFullWidth } from '../../core/Media';
import { bookmarkSelection, restoreSelection } from '../../core/Selection';
import { IFRAME_EMBED_PROVIDER_NAMES } from '../../core/Schema';

const PROVIDER_LIST = IFRAME_EMBED_PROVIDER_NAMES.join(', ');

export function openEmbedDialog(editor: Editor, target?: HTMLElement): void {
  const root = editor.getEditableElement();
  const existing = target ?? getSelectedEmbed(root);
  const current = existing ? getEmbedSrc(existing) : '';
  const bookmark = bookmarkSelection(root);

  new Dialog({
    title: existing ? 'Edit Embed' : 'Insert Embed',
    submitLabel: existing ? 'Update' : 'Insert',
    fields: [
      { name: 'code', label: 'Embed code or URL', type: 'textarea', defaultValue: current },
      {
        name: '_note',
        label:
          `Paste an "Embed" iframe snippet from a supported provider, or just its share URL. Supported: ${PROVIDER_LIST}.`,
        type: 'note',
      },
    ],
    onSubmit: (values) => {
      root.focus();
      const code = String(values.code ?? '').trim();

      const ok = existing
        ? updateEmbed(existing, code)
        : (() => {
            if (bookmark) restoreSelection(root, bookmark);
            return insertEmbed(root, code);
          })();

      if (!ok) {
        new Notification({
          message: `Couldn't recognize that embed. Supported providers: ${PROVIDER_LIST}.`,
          type: 'error',
        });
        return;
      }

      editor.execCommand('__syncAfterExternalEdit');
    },
  });
}

function buildMenuItems(editor: Editor, wrapper: HTMLElement): ContextMenuItem[] {
  const commit = () => editor.execCommand('__syncAfterExternalEdit');

  return [
    { label: 'Edit embed…', onSelect: () => openEmbedDialog(editor, wrapper) },
    { label: '', onSelect: () => {}, separator: true },
    { label: 'Align left', onSelect: () => { setMediaAlign(wrapper, 'left'); commit(); } },
    { label: 'Align center', onSelect: () => { setMediaAlign(wrapper, 'center'); commit(); } },
    { label: 'Align right', onSelect: () => { setMediaAlign(wrapper, 'right'); commit(); } },
    { label: 'No alignment', onSelect: () => { setMediaAlign(wrapper, 'none'); commit(); } },
    { label: '', onSelect: () => {}, separator: true },
    { label: 'Full width', onSelect: () => { setMediaFullWidth(wrapper); commit(); } },
    { label: '', onSelect: () => {}, separator: true },
    {
      label: 'Remove embed',
      onSelect: () => {
        removeEmbed(wrapper);
        commit();
      },
    },
  ];
}

registerToolbarButton({ name: 'embed', label: 'Insert embed', icon: 'embed', command: 'embed' });

registerPlugin('embed', (editor) => {
  editor.commands.register('embed', () => openEmbedDialog(editor));

  const resizer = editor.getMediaResizer();
  resizer.onResizeCommit(() => editor.execCommand('__syncAfterExternalEdit'));
  resizer.onMenuRequest((wrapper) => {
    if (!wrapper.classList.contains('omar-text-editor-embed')) return null;
    return buildMenuItems(editor, wrapper);
  });
});
