export interface KeyBinding {
  key: string;
  ctrl?: boolean;
  shift?: boolean;
  command: string;
  // Human-readable shortcut text for tooltips, e.g. "Ctrl+B". Generated
  // automatically from key/ctrl/shift in add() rather than passed in, so
  // it can never drift out of sync with the actual matching logic.
  label: string;
}

function formatLabel(key: string, ctrl?: boolean, shift?: boolean): string {
  const parts: string[] = [];
  if (ctrl) parts.push('Ctrl');
  if (shift) parts.push('Shift');
  parts.push(key.length === 1 ? key.toUpperCase() : key);
  return parts.join('+');
}

// Maps keydown events to command names. Editor owns dispatching the
// resolved command; this module only does the matching so bindings can be
// listed/extended independently of Editor's event wiring.
export class Keymap {
  private bindings: KeyBinding[] = [];

  add(binding: Omit<KeyBinding, 'label'>): void {
    this.bindings.push({ ...binding, label: formatLabel(binding.key, binding.ctrl, binding.shift) });
  }

  match(e: KeyboardEvent): string | null {
    const key = e.key.toLowerCase();
    const mod = e.ctrlKey || e.metaKey;

    for (const b of this.bindings) {
      if (b.key !== key) continue;
      if (!!b.ctrl !== mod) continue;
      if (!!b.shift !== e.shiftKey) continue;
      return b.command;
    }
    return null;
  }

  // Returns the first binding's label for a given command, if any — used
  // by Toolbar to append a shortcut hint to a button's tooltip.
  labelFor(command: string): string | null {
    return this.bindings.find((b) => b.command === command)?.label ?? null;
  }

  list(): readonly KeyBinding[] {
    return this.bindings;
  }
}

export function createDefaultKeymap(): Keymap {
  const km = new Keymap();
  km.add({ key: 'b', ctrl: true, command: 'bold' });
  km.add({ key: 'i', ctrl: true, command: 'italic' });
  km.add({ key: 'u', ctrl: true, command: 'underline' });
  km.add({ key: 'x', ctrl: true, shift: true, command: 'strikethrough' });
  km.add({ key: 'z', ctrl: true, command: 'undo' });
  km.add({ key: 'z', ctrl: true, shift: true, command: 'redo' });
  km.add({ key: 'y', ctrl: true, command: 'redo' });
  km.add({ key: 'k', ctrl: true, command: 'link' });
  km.add({ key: ']', ctrl: true, command: 'indent' });
  km.add({ key: '[', ctrl: true, command: 'outdent' });
  km.add({ key: 'f', ctrl: true, command: 'searchreplace' });
  return km;
}
