import type { Editor } from '../core/Editor';
import { getIconSvg, hasIcon } from './IconPack';
import { ColorPicker } from './ColorPicker';

export interface ToolbarButtonDef {
  name: string;
  label: string;
  icon: string;
  command: string;
  commandValue?: string;
  isActive?: (editor: Editor) => boolean;
  // Escape hatch for buttons whose click needs more than "fire a command
  // with a fixed value" — e.g. the table button opening a GridPicker
  // anchored at the button itself. When set, this replaces the default
  // execCommand(command, commandValue) behavior entirely.
  onClick?: (editor: Editor, buttonEl: HTMLButtonElement) => void;
}

export interface ToolbarSelectDef {
  name: string;
  label: string;
  command: string;
  options: { label: string; value: string }[];
  getCurrentValue?: (editor: Editor) => string | null;
}

