import { highlight } from './Highlighter';

function getRange(): Range | null {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0) return null;
  return sel.getRangeAt(0);
}

function findAncestor(node: Node, tags: string[]): HTMLElement | null {
  let current: Node | null = node;
  while (current) {
    if (current.nodeType === Node.ELEMENT_NODE && tags.includes((current as Element).tagName.toLowerCase())) {
      return current as HTMLElement;
    }
    current = current.parentNode;
  }
  return null;
}

function setCaretAt(node: Node, offset: number): void {
  const range = document.createRange();
  range.setStart(node, offset);
  range.setEnd(node, offset);
  const sel = window.getSelection();
  sel?.removeAllRanges();
  sel?.addRange(range);
}

// Renders `code` (raw text) into a <pre><code class="language-xxx"
// data-code="..."> block. The raw source is kept verbatim in the
// data-code attribute (HTML-escaped as an attribute value, which the
// browser unescapes back to the original text on read) so re-opening the
// dialog can recover the exact original text rather than trying to
// reverse-parse it out of the syntax-highlighted markup.
function renderCodeBlock(pre: HTMLElement, code: string, language: string): void {
  pre.classList.add('omar-text-editor-codesample');
  pre.dataset.language = language;
  pre.dataset.code = code;

  const codeEl = document.createElement('code');
  codeEl.className = `language-${language}`;
  codeEl.innerHTML = highlight(code, language);

  pre.innerHTML = '';
  pre.appendChild(codeEl);
}

export function insertCodeSample(root: HTMLElement, code: string, language: string): void {
  const pre = document.createElement('pre');
  renderCodeBlock(pre, code, language);

  const range = getRange();
  if (range) {
    range.deleteContents();
    range.insertNode(pre);
  } else {
    root.appendChild(pre);
  }

  const p = document.createElement('p');
  p.innerHTML = '<br>';
  pre.parentNode?.insertBefore(p, pre.nextSibling);
  setCaretAt(p, 0);
}

export function updateCodeSample(pre: HTMLElement, code: string, language: string): void {
  renderCodeBlock(pre, code, language);
}

export function getCurrentCodeSample(node: Node): HTMLElement | null {
  const pre = findAncestor(node, ['pre']);
  if (!pre || !pre.classList.contains('omar-text-editor-codesample')) return null;
  return pre;
}

export function getCodeSampleData(pre: HTMLElement): { code: string; language: string } {
  return {
    code: pre.dataset.code ?? '',
    language: pre.dataset.language ?? 'javascript',
  };
}
