import type { Editor } from '../../core/Editor';
import { registerPlugin } from '../../core/Editor';
import { GridPicker } from '../../ui/GridPicker';
import { ContextMenu, ContextMenuItem } from '../../ui/ContextMenu';
import { ColorPicker } from '../../ui/ColorPicker';
import { registerToolbarButton } from '../../ui/Toolbar';
import { ColumnResizer } from '../../ui/ColumnResizer';
import { RowResizer } from '../../ui/RowResizer';
import { TableResizer } from '../../ui/TableResizer';
import { TableCellSelection } from '../../ui/TableCellSelection';
import {
  insertTable,
  getCurrentCell,
  getCurrentTable,
  insertRow,
  deleteRow,
  insertColumn,
  deleteColumn,
  deleteTable,
  mergeCellRight,
  splitCell,
  toggleHeaderRow,
  navigateCell,
  mergeCellRange,
  deleteRows,
  deleteColumns,
} from '../../core/Tables';
import { bookmarkSelection, restoreSelection } from '../../core/Selection';

export function openGridPicker(editor: Editor, anchor: HTMLElement): void {
  const root = editor.getEditableElement();
  const bookmark = bookmarkSelection(root);

  new GridPicker(anchor, {
    onPick: (rows, cols) => {
      root.focus();
      if (bookmark) restoreSelection(root, bookmark);
      insertTable(root, rows, cols);
      editor.execCommand('__syncAfterExternalEdit');
    },
  });
}

function buildContextMenuItems(editor: Editor, cell: HTMLTableCellElement): ContextMenuItem[] {
  const table = getCurrentTable(cell)!;
  const row = cell.parentElement as HTMLTableRowElement;
  const colIndex = Array.prototype.indexOf.call(row.children, cell);

  const commit = () => editor.execCommand('__syncAfterExternalEdit');

  return [
    { label: 'Insert row above', onSelect: () => { insertRow(table, row, true); commit(); } },
    { label: 'Insert row below', onSelect: () => { insertRow(table, row, false); commit(); } },
    { label: 'Delete row', onSelect: () => { deleteRow(row); commit(); }, },
    { label: '', onSelect: () => {}, separator: true },
    { label: 'Insert column left', onSelect: () => { insertColumn(table, colIndex, true); commit(); } },
    { label: 'Insert column right', onSelect: () => { insertColumn(table, colIndex, false); commit(); } },
    { label: 'Delete column', onSelect: () => { deleteColumn(table, colIndex); commit(); } },
    { label: '', onSelect: () => {}, separator: true },
    { label: 'Merge with cell to the right', onSelect: () => { mergeCellRight(cell); commit(); } },
    { label: 'Split cell', onSelect: () => { splitCell(cell); commit(); } },
    { label: 'Toggle header row', onSelect: () => { toggleHeaderRow(table); commit(); } },
    { label: '', onSelect: () => {}, separator: true },
    { label: 'Delete table', onSelect: () => { deleteTable(table); commit(); } },
  ];
}

// Shown instead of the single-cell menu whenever 2+ cells are highlighted
// via drag-selection or a header strip click (see TableCellSelection).
function buildSelectionContextMenuItems(
  editor: Editor,
  table: HTMLTableElement,
  cells: HTMLTableCellElement[],
  selection: TableCellSelection,
  anchorX: number,
  anchorY: number,
): ContextMenuItem[] {
  const commit = () => {
    selection.clear();
    editor.execCommand('__syncAfterExternalEdit');
  };

  return [
    { label: 'Delete selected rows', onSelect: () => { deleteRows(table, cells); commit(); } },
    { label: 'Delete selected columns', onSelect: () => { deleteColumns(table, cells); commit(); } },
    { label: '', onSelect: () => {}, separator: true },
    { label: 'Merge cells', onSelect: () => { mergeCellRange(table, cells); commit(); } },
    { label: '', onSelect: () => {}, separator: true },
    {
      label: 'Background color…',
      onSelect: () => {
        const anchor = document.createElement('div');
        anchor.style.position = 'fixed';
        anchor.style.left = `${anchorX}px`;
        anchor.style.top = `${anchorY}px`;
        document.body.appendChild(anchor);
        new ColorPicker(anchor, {
          onPick: (color) => {
            cells.forEach((c) => { c.style.backgroundColor = color; });
            commit();
            anchor.remove();
          },
          onClear: () => {
            cells.forEach((c) => { c.style.backgroundColor = ''; });
            commit();
            anchor.remove();
          },
        });
      },
    },
  ];
}

function setupContextMenu(editor: Editor, selection: TableCellSelection): void {
  const root = editor.getEditableElement();

  root.addEventListener('contextmenu', (e) => {
    const target = e.target as Element;
    const cell = getCurrentCell(target);
    if (!cell) return;

    e.preventDefault();

    const selectedCells = selection.getSelectedCells();
    const table = selection.getSelectedTable();
    if (table && selectedCells.length > 1 && selectedCells.includes(cell)) {
      new ContextMenu(
        e.clientX,
        e.clientY,
        buildSelectionContextMenuItems(editor, table, selectedCells, selection, e.clientX, e.clientY),
      );
      return;
    }

    new ContextMenu(e.clientX, e.clientY, buildContextMenuItems(editor, cell));
  });
}

function setupTabNavigation(editor: Editor): void {
  const root = editor.getEditableElement();

  root.addEventListener('keydown', (e) => {
    if (e.key !== 'Tab') return;

    const sel = window.getSelection();
    if (!sel || sel.rangeCount === 0) return;

    const cell = getCurrentCell(sel.getRangeAt(0).startContainer);
    if (!cell) return;

    const table = getCurrentTable(cell);
    if (!table) return;

    e.preventDefault();
    if (navigateCell(table, cell, !e.shiftKey)) {
      editor.execCommand('__syncAfterExternalEdit');
    }
  });
}

registerToolbarButton({
  name: 'table',
  label: 'Insert table',
  icon: 'table',
  command: 'table',
  onClick: (editor, buttonEl) => openGridPicker(editor, buttonEl),
});

registerPlugin('table', (editor) => {
  // Also register a plain command (inserts a default 3x3 table) so `table`
  // remains callable from a future menu bar or keyboard shortcut that has
  // no button element to anchor a GridPicker popover against.
  editor.commands.register('table', () => {
    const root = editor.getEditableElement();
    root.focus();
    insertTable(root, 3, 3);
    editor.execCommand('__syncAfterExternalEdit');
  });

  // Row/column/table commands for the menu bar's Table menu, which (unlike
  // the right-click context menu) has no clicked cell to act on — these
  // operate on whichever cell the caret is currently inside instead, the
  // same "current" cell/table lookup the Tab-navigation handler uses.
  const withCurrentCell = (fn: (table: HTMLTableElement, cell: HTMLTableCellElement, colIndex: number) => void) => {
    const sel = window.getSelection();
    if (!sel || sel.rangeCount === 0) return;
    const cell = getCurrentCell(sel.getRangeAt(0).startContainer);
    if (!cell) return;
    const table = getCurrentTable(cell);
    if (!table) return;
    const row = cell.parentElement as HTMLTableRowElement;
    const colIndex = Array.prototype.indexOf.call(row.children, cell);
    fn(table, cell, colIndex);
    editor.execCommand('__syncAfterExternalEdit');
  };

  editor.commands.register('tableInsertRowBefore', () => withCurrentCell((table, cell) => {
    insertRow(table, cell.parentElement as HTMLTableRowElement, true);
  }));
  editor.commands.register('tableInsertRowAfter', () => withCurrentCell((table, cell) => {
    insertRow(table, cell.parentElement as HTMLTableRowElement, false);
  }));
  editor.commands.register('tableDeleteRow', () => withCurrentCell((_table, cell) => {
    deleteRow(cell.parentElement as HTMLTableRowElement);
  }));
  editor.commands.register('tableInsertColBefore', () => withCurrentCell((table, _cell, colIndex) => {
    insertColumn(table, colIndex, true);
  }));
  editor.commands.register('tableInsertColAfter', () => withCurrentCell((table, _cell, colIndex) => {
    insertColumn(table, colIndex, false);
  }));
  editor.commands.register('tableDeleteCol', () => withCurrentCell((table, _cell, colIndex) => {
    deleteColumn(table, colIndex);
  }));
  editor.commands.register('tableDelete', () => withCurrentCell((table) => {
    deleteTable(table);
  }));

  const selection = new TableCellSelection(editor.getEditableElement());
  selection.onChange(() => {
    // Selecting a range highlights cells directly; nothing else needs
    // syncing since content/history are untouched by selection alone.
  });

  setupContextMenu(editor, selection);
  setupTabNavigation(editor);

  const colResizer = new ColumnResizer(editor.getEditableElement());
  colResizer.onResizeCommit(() => editor.execCommand('__syncAfterExternalEdit'));

  const rowResizer = new RowResizer(editor.getEditableElement());
  rowResizer.onResizeCommit(() => editor.execCommand('__syncAfterExternalEdit'));

  const tableResizer = new TableResizer(editor.getEditableElement());
  tableResizer.onResizeCommit(() => editor.execCommand('__syncAfterExternalEdit'));
  tableResizer.onMoveCommitCb(() => editor.execCommand('__syncAfterExternalEdit'));

  // ColumnResizer/RowResizer only re-scan their handles on the native
  // `input` DOM event, which never fires for a programmatic edit (inserting
  // a table via the grid picker, a context menu row/column edit, etc. all
  // go through execCommand('__syncAfterExternalEdit') → the editor's
  // `change` event, not a real keyboard/input event) — so without this,
  // resize handles for a freshly-inserted or freshly-edited table would
  // silently never appear until the user happened to type elsewhere.
  editor.on('change', () => {
    colResizer.refresh();
    rowResizer.refresh();
  });
});
