import { isSafeUrl, isAllowedIframeSrc } from './Schema';
import { toEmbedUrl } from './Media';

function getRange(): Range | null {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0) return null;
  return sel.getRangeAt(0);
}

// Pulls the `src` attribute value out of raw pasted text via regex — never
// via innerHTML/DOM parsing into a live document, so nothing in the pasted
// string (script tags, event handler attributes, anything else) ever has a
// chance to execute or attach to the page. This is pure string extraction:
// no validation of the value itself happens here.
export function extractIframeSrc(pastedText: string): string | null {
  const match = pastedText.match(/<iframe[^>]*\ssrc\s*=\s*["']([^"']+)["']/i);
  return match ? match[1]! : null;
}

// Resolves arbitrary pasted text (an <iframe>...</iframe> snippet, or a
// bare share URL) down to a safe iframe src, or null if it can't be
// trusted. This is the sole gate a pasted embed must pass through: the
// candidate src — whether lifted from an iframe tag or derived from a bare
// URL via the same provider detection Media.ts uses — must be both a safe
// URL scheme and match the fixed embed-host allowlist in Schema.ts.
export function resolveEmbedSrc(pastedText: string): string | null {
  const trimmed = pastedText.trim();
  if (!trimmed) return null;

  const iframeSrc = extractIframeSrc(trimmed);
  const candidate = iframeSrc ?? toEmbedUrl(trimmed) ?? (/^https:\/\/www\.google\.com\/maps\/embed/i.test(trimmed) ? trimmed : null);
  if (!candidate) return null;

  if (!isSafeUrl(candidate) || !isAllowedIframeSrc(candidate)) return null;
  return candidate;
}

// Builds a fresh iframe from scratch using only the validated src plus a
// fixed, known-safe attribute set — mirrors Media.ts's buildEmbedWrapper.
// Every other attribute from the user's pasted snippet (width/height/
// frameborder/allow/onload/onerror/etc) is discarded, never read.
function buildWrapper(src: string): HTMLElement {
  const wrapper = document.createElement('div');
  wrapper.className = 'omar-text-editor-embed';

  const iframe = document.createElement('iframe');
  iframe.src = src;
  iframe.setAttribute('frameborder', '0');
  iframe.setAttribute('allowfullscreen', 'true');
  iframe.setAttribute('sandbox', 'allow-scripts allow-same-origin allow-presentation');
  wrapper.appendChild(iframe);
  return wrapper;
}

// Inserts a validated embed at the current selection (or appends to root
// if there's no live selection). Returns false without touching the DOM
// if the pasted text doesn't resolve to an allowlisted src.
export function insertEmbed(root: HTMLElement, pastedText: string): boolean {
  const src = resolveEmbedSrc(pastedText);
  if (!src) return false;

  const wrapper = buildWrapper(src);
  const range = getRange();
  if (range) {
    range.deleteContents();
    range.insertNode(wrapper);
    range.setStartAfter(wrapper);
    range.collapse(true);
    const sel = window.getSelection();
    sel?.removeAllRanges();
    sel?.addRange(range);
  } else {
    root.appendChild(wrapper);
  }

  return true;
}

// Finds the embed wrapper the caret is currently inside/adjacent to —
// mirrors Media.ts's getSelectedMediaEmbed dual range/anchorNode lookup.
export function getSelectedEmbed(root: HTMLElement): HTMLElement | null {
  const findWrapper = (node: Node | null): HTMLElement | null => {
    let current: Node | null = node;
    while (current && current !== root.parentNode) {
      if (
        current.nodeType === Node.ELEMENT_NODE &&
        (current as Element).classList.contains('omar-text-editor-embed')
      ) {
        return current as HTMLElement;
      }
      current = current.parentNode;
    }
    return null;
  };

  const range = getRange();
  if (range) {
    const fromRange = findWrapper(range.startContainer);
    if (fromRange) return fromRange;
    const node = range.startContainer.nodeType === Node.ELEMENT_NODE
      ? range.startContainer.childNodes[range.startOffset]
      : null;
    if (node) {
      const fromChild = findWrapper(node);
      if (fromChild) return fromChild;
    }
  }

  const selection = window.getSelection();
  return findWrapper(selection?.anchorNode ?? null);
}

export function getEmbedSrc(wrapper: HTMLElement): string {
  return wrapper.querySelector('iframe')?.getAttribute('src') ?? '';
}

// Rebuilds the wrapper's contents in place for the new pasted text —
// rebuilding rather than patching keeps the same "fresh iframe, fixed
// attributes" guarantee as a first-time insert.
export function updateEmbed(wrapper: HTMLElement, pastedText: string): boolean {
  const src = resolveEmbedSrc(pastedText);
  if (!src) return false;

  const built = buildWrapper(src);
  wrapper.replaceChildren(...Array.from(built.childNodes));
  return true;
}

export function removeEmbed(wrapper: HTMLElement): void {
  wrapper.remove();
}
