import { registerPlugin } from '../../core/Editor';
import { registerToolbarButton } from '../../ui/Toolbar';
import { toggleVisualBlocks, isVisualBlocksActive } from '../../core/VisualBlocks';

registerToolbarButton({
  name: 'visualblocks',
  label: 'Show blocks',
  icon: 'visualBlocks',
  command: 'visualblocks',
  isActive: (e) => isVisualBlocksActive(e.getEditableElement()),
});

registerPlugin('visualblocks', (editor) => {
  editor.commands.register('visualblocks', () => {
    toggleVisualBlocks(editor.getEditableElement());
  });
});
